  captions: [[0.0, "Red lines up west of the cone and blue east of it, behind the 35-yard line. The coach and cone are in the middle of the field."], [0.6, "The coach rolls a ball about ten yards up the field."], [1.0, "Two players from each team go out and fight for it."], [3.2, "Red wins the ground ball, so red is on offense for the whole round."], [3.6, "The next red player pops out for a free pass."], [6.2, "Free pass! Now it is 3 on 2."], [12.2, "Red has a shot and takes it: goal! The goalie went the other way."], [14.2, "The coach calls \"Release!\" The next player from each team joins: now 4 on 3."], [14.5, "Everyone gets back to the middle for the next ball."], [19.2, "The coach says \"New ball!\" and gives the offensive player nearest the 35 a free ball."], [20.2, "The offense goes again."], [25.2, "Red has a shot and takes it: the goalie makes the save."], [26.5, "The goalie has it and throws it back to the coach at the cone."], [27.2, "The coach calls \"Release!\" The next player from each team joins: now 5 on 4."], [27.5, "Everyone gets back to the middle for the next ball."], [32.2, "The coach says \"Ball in!\" and gives the offensive player nearest the 35 a free ball."], [33.2, "The offense goes again."], [40.2, "Red has a shot and takes it: goal! The goalie went the other way."], [42.2, "The coach calls \"Release a defender!\" The next defender joins to make it even: now 5 on 5."], [42.5, "Everyone gets back to the middle for the next ball."], [47.2, "The coach says \"New ball!\" and gives the offensive player nearest the 35 a free ball."], [48.2, "The offense goes again."], [57.2, "Red has a shot and takes it: goal! The goalie went the other way."], [59.6, "The coach calls \"Reset!\" and everyone goes back to the lines."]],
